function escapeHTML(valor) {
  return String(valor)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function html(literais, ...valores) {
  return literais.reduce((resultado, literal, indice) => {
    const valor = indice < valores.length ? escapeHTML(valores[indice]) : "";
    return resultado + literal + valor;
  }, "");
}

