const nome = "Marta Silva";
const curso = "JavaScript Avançado";
const dataInscricao = "16/09/2026";

const certificado = `Certificado de Conclusão
Concedido a: ${nome}
Curso: ${curso} | Data: ${dataInscricao}`;

console.log(certificado);

const produtos = [
  { nome: "Teclado mecânico", preco: 45.5, quantidade: 1 },
  { nome: "Rato sem fios", preco: 19.9, quantidade: 2 },
  { nome: "Tapete de secretária", preco: 12, quantidade: 1 },
];

const linhas = produtos
  .map((p) => `- ${p.quantidade}x ${p.nome}: ${(p.preco * p.quantidade).toFixed(2)}€`)
  .join("\n");

const total = produtos.reduce((soma, p) => soma + p.preco * p.quantidade, 0);
const numeroArtigos = produtos.reduce((soma, p) => soma + p.quantidade, 0);

const recibo = `${linhas}
Total: ${total.toFixed(2)}€ (${numeroArtigos} ${numeroArtigos === 1 ? "artigo" : "artigos"})`;

console.log(recibo);

function escapeHTML(valor) {
  return String(valor)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function destaque(literais, ...valores) {
  return literais.reduce((resultado, literal, indice) => {
    if (indice === valores.length) {
      return resultado + literal;
    }
    const valorEscapado = escapeHTML(valores[indice]);
    return resultado + literal + `<mark>${valorEscapado}</mark>`;
  }, "");
}

const termo = "<b>preço</b>";
const resultado = destaque`Resultados para ${termo}: encontrados 3 artigos.`;
console.log(resultado);
// Resultados para <mark>&lt;b&gt;preço&lt;/b&gt;</mark>: encontrados 3 artigos.
